import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount, lineVAT } from './invoices.js';

/**
 * Get invoices that are overdue as of a given date.
 * @param {Array<object>} invoices - All invoices to filter from
 * @param {string} asOf - Date in YYYY-MM-DD format (report date)
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => ['issued', 'partially_paid'].includes(inv.status))
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get VAT summary across invoices.
 * @param {Array<object>} invoices - All invoices to summarize
 * @returns {Array<{ rate: number, base: number, vat: number }>} Sorted by rate descending
 */
export function vatSummary(invoices) {
  // Accumulate by VAT rate
  const vatByRate = {};

  invoices
    .filter((inv) => ['issued', 'partially_paid', 'paid'].includes(inv.status))
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const rate = line.vatRate;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVAT(line);

        if (!vatByRate[rate]) {
          vatByRate[rate] = { rate, base: 0, vat: 0 };
        }
        vatByRate[rate].base += base;
        vatByRate[rate].vat += vat;
      });
    });

  // Convert to array and sort by rate descending
  return Object.values(vatByRate).sort((a, b) => b.rate - a.rate);
}

