  assert.equal(issued.ok, true);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // base = lineTotal - lineDiscount = 95000 - 9500 = 85500
  assert.equal(result[0].base, 85500);
  // vat = 85500 * 0.21 = 17955
  assert.equal(result[0].vat, 17955);
});

test('vatSummary handles multiple VAT rates', () => {
